// Builds the agent-legible (GEO) layer of fa1.dev — gh-1476.
//
//   dart scripts/build_site.dart              # build into site/ (local preview)
//   dart scripts/build_site.dart --out <dir>  # complete site tree at <dir>
//
// Generated artifacts are DEPLOY-TIME PRODUCTS (gh-1476 owner directive,
// PR #1479): they are gitignored and never committed — the repo holds
// sources only (blog/posts, docs/*.md, site/*.html|txt|css). Generation
// points:
//   - pages.yml deploys: `--out build/pages` is the ONLY place the
//     artifacts exist at deploy time;
//   - ci.yml validates: `--out <tmp>` + test/site/* (crawl/schema/llms
//     guards) run against the temp output via FA_SITE_ROOT;
//   - `dart test test/site/` locally: builds to a temp dir on demand when
//     site/ carries no built layer yet.
//
// What it generates (site-relative paths):
//   site/blog/<slug>/index.html  — static post pages, raw-HTML content,
//                                  BlogPosting JSON-LD (no JS needed)
//   site/docs/<slug>/index.html  — curated docs/*.md as TechArticle pages
//   site/blog/index.html         — rendered from index.template.html: the
//                                  post-list block between the
//                                  #blog-post-list markers
//   site/sitemap.xml             — every indexable page, real lastmod
//   site/llms-full.txt           — llms.txt + full curated post/doc text
//
// lastmod discipline (deterministic from committed inputs — no git, no
// mtimes, so any checkout rebuilds byte-identically): blog posts take
// front-matter `updated:`/`date:` (filename date prefix as fallback; a
// post with none of these fails the build), docs take the `updated`
// field of their [_docsRegistry] entry (bump it when the source doc
// changes), static pages take [_staticPages].
//
// Pure Dart + dart:io, no package deps (same convention as
// scripts/build_blog.dart).

import 'dart:convert';
import 'dart:io';

import 'site_markdown.dart';

const siteOrigin = 'https://fa1.dev';
const orgName = 'IstiN';
const orgUrl = 'https://github.com/IstiN';
const repoUrl = 'https://github.com/IstiN/flutter_agent_harness';
const pubDevUrl = 'https://pub.dev/packages/flutter_agent_harness';

/// Hard cap for llms-full.txt (gh-1476 threat model: a context-window
/// budget, not a repo dump).
const llmsFullBudgetBytes = 150 * 1024;

/// One sitemap entry.
class SitePage {
  const SitePage(this.loc, this.lastmod, this.changefreq, this.priority);
  final String loc;
  final String lastmod;
  final String changefreq;
  final String priority;
}

/// A curated docs/*.md page surfaced as static HTML (gh-1476 D5).
class DocsSource {
  const DocsSource(this.slug, this.source, this.updated, this.description);
  final String slug;
  final String source; // repo-relative markdown path
  final String updated; // YYYY-MM-DD — bump when the source doc changes
  final String description; // for OG/JSON-LD when the doc has no lede
}

/// Agent-quotable docs surfaced under /docs/ (bounded by design — a full
/// docs site is a separate card). `updated` mirrors the source's last
/// meaningful change.
const docsRegistry = [
  DocsSource(
    'tool-availability',
    'docs/tool-availability.md',
    '2026-10-10',
    'Per-tool availability in Fa: how the tools: config section stacks '
        'global, project, session, and runtime scopes over the host '
        'capability floor, and how load modes decide what is loaded.',

// GEO invariant tests for fa1.dev (gh-1476) — the no-JS crawl contract:
// every meaningful page serves its core text as raw HTML, robots.txt
// welcomes the named AI crawlers, llms.txt/llms-full.txt are served as
// text/plain with canonical-URL section headers, every JSON-LD block
// parses, and every sitemap <loc> resolves. Served over a real loopback
// HttpServer from the resolved site root — zero JavaScript involved.
//
// The root comes from test/site_test_support.dart: FA_SITE_ROOT, the
// in-tree site/, or an on-the-fly temp build (generated artifacts are
// deploy-time products, never committed — PR #1479 owner directive).
import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';

import '../site_test_support.dart';

/// URL path → file under [root], mirroring GitHub Pages' static serving.
String? resolveSiteFile(String root, String path) {
  if (path.contains('..')) return null;
  final rel = path.endsWith('/')
      ? '${path.substring(0, path.length - 1)}/index.html'
      : path;
  if (rel.isEmpty || rel == 'index.html') return '$root/index.html';
  final file = '$root$rel';
  return File(file).existsSync() ? file : null;
}

void main() {
  late Directory siteRoot;
  late HttpServer server;
  late String origin;
  late String sitemap;
  late List<String> locs;

  setUpAll(() async {
    siteRoot = await resolveSiteRoot();
    sitemap = File('${siteRoot.path}/sitemap.xml').readAsStringSync();
    locs = RegExp(r'<loc>(https://fa1\.dev[^<]+)</loc>')
        .allMatches(sitemap)
        .map((m) => m.group(1)!)
        .toList();

    server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    origin = 'http://127.0.0.1:${server.port}';
    server.listen((req) async {
      final path = Uri.decodeComponent(req.uri.path);
      final file = resolveSiteFile(siteRoot.path, path);
      if (file == null) {
        req.response
          ..statusCode = HttpStatus.notFound
          ..write('not found');
      } else {
        final ext = file.split('.').last;
        req.response.headers.contentType = switch (ext) {
          'html' => ContentType.html,
          'txt' => ContentType.text,
          'xml' => ContentType.parse('application/xml'),
          'png' => ContentType.parse('image/png'),
          'svg' => ContentType.parse('image/svg+xml'),
          'json' => ContentType.json,
          _ => ContentType.binary,
        };
        await req.response.addStream(File(file).openRead());
      }
      await req.response.close();
    });
  });

  tearDownAll(() => server.close(force: true));

  Future<(int, String, String?)> get(String path) async {
    final client = HttpClient();
    try {
      final req = await client.getUrl(Uri.parse('$origin$path'));
      final res = await req.close();
      final body = await utf8.decoder.bind(res).join();
      return (res.statusCode, body, res.headers.contentType?.mimeType);
    } finally {
      client.close(force: true);
    }
  }

  group('no-JS crawl (gh-1476 test matrix)', () {
    test('every sitemap <loc> returns 200', () async {
      expect(locs, isNotEmpty);
      for (final loc in locs) {
        final path = loc.substring('https://fa1.dev'.length);
        // /app/ is the Flutter web demo built at deploy time — absent
        // from the static tree by design.
        if (path == '/app/') continue;
        final (status, _, _) = await get(path.isEmpty ? '/' : path);
        expect(status, 200, reason: '$loc must serve without JS');
      }
    });

    test('landing page carries its core text raw', () async {
      final (status, body, type) = await get('/');
      expect(status, 200);
